        "Repeat the abnormal test at 3 months - skipping this is the commonest missed step in Indian practice.",
        "**G categories (eGFR, mL/min/1.73 m2):** G1 90 or more, G2 60-89, G3a 45-59, G3b 30-44, G4 15-29, G5 below 15 (kidney failure). [KDIGO 2024]",
