        "Restrict sodium to under 2 g/day (under 5 g of salt). [KDIGO 2021]",
        "**Pillar 2 - RAS blockade:** ACE inhibitor or ARB at the **maximum tolerated dose** in CKD with hypertension and ACR 30 mg/g or more. [KDIGO 2024]",
