        "Uric acid stones are associated with gout, obesity, the metabolic syndrome, chronic diarrhoea and a high purine intake.",
        "Uric acid is the one stone that can be **dissolved medically by alkalinising the urine**.",
        "**Struvite / magnesium ammonium phosphate (about 5-10%)** is the infection stone.",
        "Struvite is formed by **urease-producing organisms - Proteus mirabilis, Klebsiella, Pseudomonas, Ureaplasma - never Escherichia coli**.",
        "These split urea and alkalinise the urine above pH 7.2, growing into **staghorn calculi**.",
        "Struvite is commoner in women and the catheterised, and **must be completely cleared surgically** as any residual fragment reseeds the infection.",
