        "Cystinuria presents in childhood or early adult life with recurrent stones and **hexagonal crystals on microscopy**.",
        "The cystine stone is faintly opaque with a ground-glass appearance.",
        "**Drug-related stones:** indinavir, atazanavir, triamterene, sulfadiazine, and ceftriaxone (biliary and urinary sludge).",
        "**Topiramate and acetazolamide cause calcium phosphate stones** through a drug-induced distal renal tubular acidosis.",
