        "Colic is accompanied by nausea, vomiting and **microscopic or visible haematuria in about 85%**.",
        "The site of pain follows the stone: renal pelvis or upper ureter gives flank pain.",
        "A mid-ureteric stone gives pain radiating to the iliac fossa - mimics appendicitis on the right.",
        "**A vesicoureteric junction stone gives suprapubic pain with frequency, urgency and dysuria**, referred to the tip of the penis or the labia majora.",
        "**Absence of haematuria does not exclude a stone** - about 15% have none, particularly with complete obstruction.",
