        "False positives: concentrated urine, alkaline urine above pH 8, gross haematuria, pyuria, semen, vaginal secretions, chlorhexidine.",
        "False negatives: dilute urine, and non-albumin proteins.",
        "**Quantify with a spot first-morning urine albumin-creatinine ratio (ACR) in mg/g** for screening and staging. [KDIGO 2024]",
        "Use the **protein-creatinine ratio (PCR) in mg/g** when proteinuria is heavy or non-albumin protein is suspected.",
        "**A PCR of 1000 mg/g approximates 1 g of protein per day** - an adult excretes roughly 1 g of creatinine daily.",
        "This spot-ratio approximation makes the 24-hour collection largely unnecessary.",
        "**KDIGO albuminuria categories: A1 under 30 mg/g, A2 30-300 mg/g, A3 above 300 mg/g.** [KDIGO 2024]",
        "**Nephrotic-range proteinuria is a PCR above 3000 mg/g, equivalent to more than 3.5 g/day.**",
        "Proteinuria is transient after fever, vigorous exercise, heart failure, seizures and urinary infection.",
        "Confirm before labelling: repeat an abnormal result on 2 of 3 first-morning specimens over 3-6 months, having treated any infection.",
        "**Orthostatic (postural) proteinuria** is benign in adolescents and young adults.",
        "Protein is present in the daytime upright sample and **absent in the first-morning recumbent sample** - needs only reassurance and a check every year or two.",
