        "Lipiduria shows oval fat bodies and a Maltese cross under polarised light; the sediment is otherwise **bland - no red cell casts**.",
        "**Minimal change disease is the commonest cause in children (about 90% under 10 years)** and responds dramatically to steroids.",
        "**Focal segmental glomerulosclerosis is the commonest primary cause in Indian adults** and in adults of African ancestry.",
        "**Membranous nephropathy is the classic primary cause in older adults - anti-PLA2R positive in 70-80%**, which can make a biopsy unnecessary.",
        "Membranoproliferative glomerulonephritis is now reclassified as immune-complex-mediated or complement-mediated (C3 glomerulopathy).",
        "**Diabetes mellitus is by far the commonest cause of nephrotic syndrome overall.**",
        "Amyloidosis: AA from chronic TB, bronchiectasis, leprosy, osteomyelitis and rheumatoid arthritis; AL from plasma cell dyscrasia.",
